SELECT store_id, QUARTER(last_restock) AS last_restock_quarter, CASE WHEN quantity >= 220 THEN 'high' WHEN quantity >= 117 THEN 'mid' ELSE 'low' END AS quantity_bucket, MAX(quantity) - MIN(quantity) AS quantity_range, MIN(quantity) AS min_quantity FROM inventory WHERE product_id IN (2, 3) GROUP BY store_id, last_restock_quarter, quantity_bucket HAVING COUNT(DISTINCT quantity) >= 3 ORDER BY 4
